//! 🧪️ Actual original Draw custody, native heap receipts and shared refusal witnesses reach the same preparation frontier.
use super::*;
use semio_framework_io_ports::{ChildAdmissionRead,EmbeddedChildAdmitterV1,OriginalChildVectorPreparation,erase_child_admission_source};
use semio_framework_value::retained_clone::RetainedCloneSource;
use semio_framework_value_testing_allocator::observe_retirement_allocations;
use crate::validation::DRAWING_ADMITTER;
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn g(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observed<T>(grant:RetainedCloneGrant,operation:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),heap)=observe_retirement_allocations(operation);assert!(p.fits(grant));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));result}
fn refuse_axes(d:RetirementDemand,mut operation:impl FnMut(RetainedCloneGrant)->RetainedCloneProgress){let original=g(d);for axis in 0..5{let mut denied=original;let value=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *value==0{continue}*value-=1;let(p,heap)=observe_retirement_allocations(||operation(denied));assert_eq!(p,Default::default());assert_eq!(heap,(0,0));}}
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../✅️validation/🧪️.json")).unwrap()}
fn patched(base:&serde_json::Value,patches:&serde_json::Value)->serde_json::Value{let mut value=base.clone();for patch in patches.as_array().unwrap(){let at=patch["path"].as_str().unwrap();if patch["op"]=="remove"{value.as_object_mut().unwrap().remove("artboard");}else{*value.pointer_mut(at).unwrap()=patch["value"].clone()}}value}
fn run(value:serde_json::Value,valid:bool,cut:Option<usize>){let expected:DrawingSnapshot=serde_json::from_value(value.clone()).unwrap();let(mut source,_)=RetainedCloneSource::admit_owned(expected.clone(),(),generous()).unwrap_or_else(|_|panic!("original Drawing owner"));let d=OriginalChildVectorPreparation::birth_demand();let mut owner=observed(g(d),||{let(owner,p)=OriginalChildVectorPreparation::admit(g(d)).unwrap();(owner,p)});let mut capacity=0;let mut release=0;let mut done=false;
 for _ in 0..cut.unwrap_or(100000){let read=ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),0x4348494c),admitter:&DRAWING_ADMITTER,vector:&DRAWING_VECTOR_SOURCE};let d=owner.next_demand(&read,16*1024*1024).unwrap();refuse_axes(d,|grant|owner.advance(&read,grant).unwrap().progress);let step=observed(g(d),||{let step=owner.advance(&read,g(d)).unwrap();let p=step.progress;(step,p)});capacity+=step.progress.retained_capacity_bytes;release+=step.progress.released_bytes;if step.done{assert_eq!(capacity,release);done=true;assert_eq!(step.error.is_none(),valid);assert_eq!(step.graph.is_some(),valid);if let Some(graph)=step.graph{assert_eq!(graph as*const dyn VectorGraphSourceV1 as*const (),source.borrow().get()as*const DrawingSnapshot as*const ());assert_eq!(graph.root_count(),expected.layers.len());assert_eq!(step.canvas.is_some(),value.get("artboard").is_some());}break}}
 if cut.is_none(){assert!(done)}owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demand(16*1024*1024).unwrap();refuse_axes(d,|grant|owner.close_step(grant).unwrap().progress());let p=observed(g(d),||{let p=owner.close_step(g(d)).unwrap().progress();(p,p)});capacity+=p.retained_capacity_bytes;release+=p.released_bytes;}assert!(owner.terminal_is_empty());assert_eq!(capacity,release);assert_eq!(source.try_authority().unwrap(),&expected);while !source.terminal_is_empty(){let d=source.next_close_demand(16*1024*1024).unwrap();source.close_step(g(d)).unwrap();}}
#[test]
fn genuine_vector_preparation_matches_shared_owned_admission_oracle_and_physical_receipts(){let laws:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🔌️ports/🧩️admission/🧵️vector/🧳️prepare/🧪️.json")).unwrap();assert_eq!(laws["cases"].as_array().unwrap().len(),13);let corpus=corpus();for case in corpus["cases"].as_array().unwrap(){run(patched(&corpus["base"],&case["patch"]),case["valid"].as_bool().unwrap(),None)}for cut in laws["cases"][8]["cuts"].as_array().unwrap(){run(corpus["base"].clone(),true,Some(cut.as_u64().unwrap()as usize))}}
struct OtherAdmitter;
impl EmbeddedChildAdmitterV1 for OtherAdmitter{fn birth_demand(&self)->RetirementDemand{DRAWING_ADMITTER.birth_demand()}fn begin(&self,g:RetainedCloneGrant)->Result<(semio_framework_io_ports::EmbeddedChildAdmission,RetainedCloneProgress),ValueError>{DRAWING_ADMITTER.begin(g)}}
static OTHER_ADMITTER:OtherAdmitter=OtherAdmitter;
struct OtherVector;
impl EmbeddedChildVectorSourceV1 for OtherVector{fn read_demand(&self)->RetirementDemand{DRAWING_VECTOR_SOURCE.read_demand()}fn read<'a>(&self,s:ChildAdmissionSource<'a>,g:RetainedCloneGrant)->Result<VectorGraphAdvance<'a>,ValueError>{DRAWING_VECTOR_SOURCE.read(s,g)}}
static OTHER_VECTOR:OtherVector=OtherVector;
#[test]
fn original_source_projection_and_registered_pair_cannot_change(){let document:DrawingSnapshot=serde_json::from_value(corpus()["base"].clone()).unwrap();let(mut source,_)=RetainedCloneSource::admit_owned(document.clone(),(),generous()).unwrap_or_else(|_|panic!("first source"));let(mut other,_)=RetainedCloneSource::admit_owned(document,(),generous()).unwrap_or_else(|_|panic!("second source"));let(mut owner,_)=OriginalChildVectorPreparation::admit(g(OriginalChildVectorPreparation::birth_demand())).unwrap();{let read=ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),1),admitter:&DRAWING_ADMITTER,vector:&DRAWING_VECTOR_SOURCE};let d=owner.next_demand(&read,8192).unwrap();owner.advance(&read,g(d)).unwrap();}for read in [ChildAdmissionRead{source:erase_child_admission_source(other.borrow(),1),admitter:&DRAWING_ADMITTER,vector:&DRAWING_VECTOR_SOURCE},ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),2),admitter:&DRAWING_ADMITTER,vector:&DRAWING_VECTOR_SOURCE},ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),1),admitter:&OTHER_ADMITTER,vector:&DRAWING_VECTOR_SOURCE},ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),1),admitter:&DRAWING_ADMITTER,vector:&OTHER_VECTOR}]{let(result,heap)=observe_retirement_allocations(||owner.next_demand(&read,8192));assert!(result.is_err());assert_eq!(heap,(0,0));}owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(8192).unwrap();owner.close_step(g(d)).unwrap();}while !source.terminal_is_empty(){source.close_step(generous()).unwrap();}while !other.terminal_is_empty(){other.close_step(generous()).unwrap();}}

struct FailingVector;
impl EmbeddedChildVectorSourceV1 for FailingVector{fn read_demand(&self)->RetirementDemand{DRAWING_VECTOR_SOURCE.read_demand()}fn read<'a>(&self,s:ChildAdmissionSource<'a>,g:RetainedCloneGrant)->Result<VectorGraphAdvance<'a>,ValueError>{let step=DRAWING_VECTOR_SOURCE.read(s,g)?;Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Paid consumer refusal").with_retained_progress(step.progress))}}
static FAILING_VECTOR:FailingVector=FailingVector;
#[test]
fn paid_consumer_error_keeps_original_custody_and_exact_receipt(){let document:DrawingSnapshot=serde_json::from_value(corpus()["base"].clone()).unwrap();let(mut source,_)=RetainedCloneSource::admit_owned(document,(),generous()).unwrap_or_else(|_|panic!("original owner"));let(mut owner,_)=OriginalChildVectorPreparation::admit(g(OriginalChildVectorPreparation::birth_demand())).unwrap();let mut failed=false;for _ in 0..100000{let read=ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),1),admitter:&DRAWING_ADMITTER,vector:&FAILING_VECTOR};let d=owner.next_demand(&read,16*1024*1024).unwrap();let(result,heap)=observe_retirement_allocations(||owner.advance(&read,g(d)));match result{Ok(step)=>{assert!(step.progress.fits(g(d)));assert_eq!(heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes));},Err(error)=>{assert_eq!(error.retained_progress().copied_bytes,d.copy_bytes);assert!(error.retained_progress().fits(g(d)));assert_eq!(heap,(error.retained_progress().retained_capacity_bytes,error.retained_progress().released_bytes));failed=true;break}}}assert!(failed);owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(8192).unwrap();owner.close_step(g(d)).unwrap();}while !source.terminal_is_empty(){source.close_step(generous()).unwrap();}}

struct MalformedVector{present:bool}
impl EmbeddedChildVectorSourceV1 for MalformedVector{fn read_demand(&self)->RetirementDemand{DRAWING_VECTOR_SOURCE.read_demand()}fn read<'a>(&self,s:ChildAdmissionSource<'a>,g:RetainedCloneGrant)->Result<VectorGraphAdvance<'a>,ValueError>{let mut step=DRAWING_VECTOR_SOURCE.read(s,g)?;step.done=!self.present;if !self.present{step.graph=None}Ok(step)}}
static PREMATURE_VECTOR:MalformedVector=MalformedVector{present:true};static MISSING_VECTOR:MalformedVector=MalformedVector{present:false};
#[test]
fn graph_publication_requires_complete_original_read_custody(){for vector in [&PREMATURE_VECTOR,&MISSING_VECTOR]{let document:DrawingSnapshot=serde_json::from_value(corpus()["base"].clone()).unwrap();let(mut source,_)=RetainedCloneSource::admit_owned(document,(),generous()).unwrap_or_else(|_|panic!("original owner"));let(mut owner,_)=OriginalChildVectorPreparation::admit(g(OriginalChildVectorPreparation::birth_demand())).unwrap();let mut failed=false;for _ in 0..100000{let read=ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),1),admitter:&DRAWING_ADMITTER,vector};let d=owner.next_demand(&read,16*1024*1024).unwrap();let(result,heap)=observe_retirement_allocations(||owner.advance(&read,g(d)));match result{Ok(step)=>{assert!(step.graph.is_none());assert_eq!(heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes));},Err(error)=>{assert_eq!(error.retained_progress().copied_bytes,d.copy_bytes);assert!(error.retained_progress().fits(g(d)));assert_eq!(heap,(0,0));failed=true;break}}}assert!(failed);owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(8192).unwrap();owner.close_step(g(d)).unwrap();}while !source.terminal_is_empty(){source.close_step(generous()).unwrap();}}}
